/** Aster-only markets not covered above fall back to this honest template. */
const generic = (symbol: string): MarketInfo => ({
  name: symbol,
  about: `${symbol} is a perpetual market listed on the venue shown below. Perpetuals are leveraged contracts that track the underlying price without an expiry date; funding payments between longs and shorts keep the contract near spot.`,
});

export function getMarketInfo(symbol: string): MarketInfo {
  return INFO[symbol] ?? generic(symbol);
}

export function marketName(symbol: string): string {
  return (INFO[symbol] ?? generic(symbol)).name;
}

export interface MarketStats { volume: string; openInterest: string; funding: string; fundingTime: string }

/** BTC's values mirror Trust's page; other markets derive from their volume. */
export function getMarketStats(m: PerpMarket): MarketStats {
  const short = m.symbol.replace(/[^A-Z]/g, '');
  if (m.symbol === 'BTC') {
    return { volume: '1.74B USDC', openInterest: '3.50B USDC', funding: '0.0013%', fundingTime: '07:40:01' };
  }
  const vol = m.volume.replace(' Vol', '').replace('$', '').replace(/ /g, '');
  const scale = (m.price + short.length) % 191 / 100 + 0.9; // 0.9x - 2.8x of volume
  const oi = (() => {
    const n = parseFloat(vol.replace(/[^0-9.]/g, ''));
    const suf = vol.endsWith('B') ? 'B' : vol.endsWith('M') ? 'M' : vol.endsWith('K') ? 'K' : '';
    const mult = suf === 'B' ? 1 : suf === 'M' ? 0.001 : 0.000001;
    const v = n * (suf ? 1 : 1) * mult * scale;
    if (v >= 1) return `${v.toFixed(2)}B USDC`;
    if (v >= 0.001) return `${(v * 1000).toFixed(2)}M USDC`;
    return `${(v * 1000000).toFixed(2)}K USDC`;
  })();
  const funding = (0.0005 + ((short.charCodeAt(0) % 40) / 10000)).toFixed(4).replace(/^0/, '0.');
  return { volume: `${vol} USDC`, openInterest: oi, funding: `${funding}%`, fundingTime: '07:40:01' };
}

/** Up to six related markets from the same venue, excluding the current one. */
export function relatedMarkets(m: PerpMarket): PerpMarket[] {
  const all = PERP_SECTIONS.flatMap((s) => s.markets)
    .filter((x) => (x.venue ?? 'hyperliquid') === (m.venue ?? 'hyperliquid') && x.symbol !== m.symbol);
  const seen = new Set<string>();
  return all
    .filter((x) => (seen.has(x.symbol) ? false : (seen.add(x.symbol), true)))
    .slice(0, 6);
}
